export const optionCrtOpListReducer = (state = { options: [] }, action) => {
  const { type, payload } = action;
  switch (type) {
    case OPTION_CRTOP_LIST_REQUEST:
      return { loading: true, options: [] };
    case OPTION_CRTOP_LIST_SUCCESS:
      const savedLocalOptions = localStorage.getItem("options")
        ? JSON.parse(localStorage.getItem("options"))
        : [];

      savedLocalOptions.sort((a, b) => {
        const dateA = new Date(b.createdAt);
        const dateB = new Date(a.createdAt);

        if (dateA < dateB) {
          return -1;
        }
        if (dateA > dateB) {
          return 1;
        }
        return 0;
      });

      return {
        success: true,
        options: [...savedLocalOptions, ...payload],
      };
    case OPTION_CRTOP_LIST_ADD:
      return {
        success: true,
        options: [payload, ...state.options],
      };
    case OPTION_CRTOP_LIST_REMOVE:
      return {
        success: true,
        options: state.options.map((op) => {
          if (String(op._id) === String(payload)) op.isDeleted = !op.isDeleted;
          if (!op.notSavedYet) return op;
        }),
      };

    case OPTION_CRTOP_LIST_UPDATE:
      return {
        success: true,
        options: state.options.map((op) => {
          if (String(op._id) === String(payload._id)) {
            op.libelle = payload.libelle;
            op.typeProcessus = payload.typeProcessus;
            op.header = payload.header;
            op.proprietaireDeDonnees = payload.proprietaireDeDonnees;
            op.sousCategorie = payload.sousCategorie;
            op.service = payload.service;
          }
          return op;
        }),
      };

    case OPTION_CRTOP_LIST_FAIL:
      return { loading: false, error: payload, options: [], success: true };
    case OPTION_CRTOP_LIST_RESET:
      return { options: [] };
    default:
      return state;
  }
};

